//! Whole immutable original consumer extraction; no native context receipt.
use crate::lint::Registry;
#[path="../fixtures/original_policies/untracked_inputs.rs"]mod original;
#[path="../fixtures/native-untracked-inputs/fixture.rs"]mod fixture;
#[path="../../dmb/shared/test_scratch.rs"]mod scratch;
fn record(outcome:&crate::run::Outcome)->serde_json::Value{serde_json::json!({"sites":outcome.run.sites,"notes":outcome.run.notes,"allow_used":outcome.allow_used,"failed":outcome.failed,"text":outcome.text})}
#[test]fn shared_untracked_input_consumer_preserves_whole_old_group_counts_scope_allow_and_reports(){for case in fixture::CASES{let root=scratch::dir(&format!("untracked-consumer-core-{case}"));for(relative,bytes)in fixture::files(case).unwrap(){let target=root.join(relative);std::fs::create_dir_all(target.parent().unwrap()).unwrap();std::fs::write(target,bytes).unwrap();}let options=crate::run::Options{root:root.clone(),lints:vec!["untracked_inputs".into()],no_cache:true,raw:true,..Default::default()};let mut registry=Registry::default();original::register(&mut registry);let old=crate::run::Engine::new(registry,options.clone()).unwrap();assert!(crate::sem::sem_for(&old.tree).unwrap().errors.is_empty(),"old fixture must genuinely prepare without parse errors");let current=crate::run::Engine::new(crate::run::registry(),options).unwrap();let expected=old.run_one(old.reg.lints[0].as_ref());let selected=current.reg.lints.iter().find(|lint|lint.meta().name=="untracked_inputs").unwrap();let actual=current.run_one(selected.as_ref());assert_eq!(record(&actual),record(&expected),"entire ordered grouping/reader identity/ALLOW/failure/report for {case}");if *case=="basic"{assert!(!expected.run.sites.is_empty(),"real dynamic read must produce actual untracked input evidence");}if *case=="sampled"{assert!(expected.run.sites.iter().any(|row|row.rule=="sampled_in_look"));}if *case=="exempt"{assert!(expected.run.sites.is_empty());}println!("SHARED_UNTRACKED_INPUTS_OLD_POLICY={}",serde_json::json!({"case":case,"record":record(&actual)}));}}
